using System;
using System.Collections.Concurrent;
using System.Threading;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Text;

namespace MonitoringAgent
{
    public sealed class ConnectionPool
    {
        private readonly ConcurrentQueue<PooledConnection> _available = new();
        private readonly SemaphoreSlim _semaphore;
        private readonly int _maxSize;
        private int _currentCount;

        public ConnectionPool(int maxSize = 10)
        {
            _maxSize = maxSize;
            _semaphore = new SemaphoreSlim(maxSize, maxSize);
        }

        public async Task<PooledConnection> AcquireAsync(CancellationToken ct = default)
        {
            await _semaphore.WaitAsync(ct);
            if (_available.TryDequeue(out var conn) && conn.IsValid)
                return conn;
            return new PooledConnection(Interlocked.Increment(ref _currentCount));
        }

        public void Release(PooledConnection conn)
        {
            if (conn.IsValid)
                _available.Enqueue(conn);
            _semaphore.Release();
        }
    }

    public class PooledConnection
    {
        public int Id { get; }
        public bool IsValid => !_disposed;
        private bool _disposed;
        public DateTime LastUsed { get; set; } = DateTime.UtcNow;

        public PooledConnection(int id) => Id = id;
        public void Dispose() => _disposed = true;
    }

    public class MetricsBatcher
    {
        private readonly ConcurrentDictionary<string, long> _counters = new();
        private readonly ConnectionPool _pool;
        private readonly object _flushLock = new();
        private volatile int _flushGeneration;

        public MetricsBatcher(ConnectionPool pool) => _pool = pool;

        public void Increment(string metric, long value = 1)
        {
            _counters.AddOrUpdate(metric, value, (_, existing) => existing + value);
        }

        public async Task<FlushResult> FlushAsync()
        {
            var generation = _flushGeneration;
            var snapshot = new ConcurrentDictionary<string, long>();

            foreach (var kvp in _counters)
            {
                if (_counters.TryRemove(kvp.Key, out var val))
                    snapshot.TryAdd(kvp.Key, val);
            }

            var conn = await _pool.AcquireAsync();
            try
            {
                var result = new FlushResult { Generation = generation, ItemCount = snapshot.Count };
                // Simulate write to monitoring backend
                await Task.Delay(5);
                Interlocked.Increment(ref _flushGeneration);
                return result;
            }
            finally
            {
                _pool.Release(conn);
            }
        }
    }

    public struct FlushResult
    {
        public int Generation;
        public int ItemCount;
    }

    public class TokenBucket
    {
        private long _tokens;
        private readonly long _maxTokens;
        private readonly long _refillRate;
        private long _lastRefillTicks;
        private readonly object _lock = new();

        public TokenBucket(long maxTokens, long refillRatePerSecond)
        {
            _maxTokens = maxTokens;
            _refillRate = refillRatePerSecond;
            _tokens = maxTokens;
            _lastRefillTicks = DateTime.UtcNow.Ticks;
        }

        public bool TryConsume(long requested)
        {
            lock (_lock)
            {
                Refill();
                if (_tokens < requested) return false;
                _tokens -= requested;
                return true;
            }
        }

        private void Refill()
        {
            var now = DateTime.UtcNow.Ticks;
            var elapsed = (now - _lastRefillTicks) / TimeSpan.TicksPerSecond;
            if (elapsed <= 0) return;

            var tokensToAdd = elapsed * _refillRate;
            _lastRefillTicks = now;
            _tokens = Math.Min(_tokens + tokensToAdd, _maxTokens);
        }
    }

    public class RateLimitedLogger
    {
        private readonly TokenBucket _bucket;
        private readonly MetricsBatcher _batcher;
        private readonly ConnectionPool _pool;

        public RateLimitedLogger(int maxEventsPerSecond = 100)
        {
            _pool = new ConnectionPool(5);
            _bucket = new TokenBucket(maxEventsPerSecond, maxEventsPerSecond);
            _batcher = new MetricsBatcher(_pool);
        }

        public async Task<bool> LogEventAsync(string source, string message)
        {
            if (!_bucket.TryConsume(1))
            {
                _batcher.Increment("rate_limited_events");
                return false;
            }

            var conn = await _pool.AcquireAsync();
            try
            {
                var sanitized = SanitizeInput(source, message);
                await WriteLogEntryAsync(conn, sanitized);
                _batcher.Increment("logged_events");
                return true;
            }
            finally
            {
                _pool.Release(conn);
            }
        }

        public async Task<bool> BurstLogAsync(string source, string[] messages)
        {
            if (!_bucket.TryConsume(messages.Length))
            {
                _batcher.Increment("burst_rejected");
                return false;
            }

            var conn = await _pool.AcquireAsync();
            try
            {
                foreach (var msg in messages)
                {
                    var sanitized = SanitizeInput(source, msg);
                    await WriteLogEntryAsync(conn, sanitized);
                }
                _batcher.Increment("burst_events", messages.Length);
                return true;
            }
            finally
            {
                _pool.Release(conn);
            }
        }

        private string SanitizeInput(string source, string message)
        {
            var clean = message.Replace("\r", "").Replace("\n", " ");
            var src = source.Replace("..", "").Replace("/", "").Replace("\\", "");
            return $"[{DateTime.UtcNow:O}] [{src}] {clean}";
        }

        private async Task WriteLogEntryAsync(PooledConnection conn, string entry)
        {
            conn.LastUsed = DateTime.UtcNow;
            await Task.Delay(1); // Simulate I/O
        }
    }
